// ========================================
// NORMALIZE MESSAGE
// Handles: text messages, callback_query,
// edited_message, and extracts metadata.
// ========================================
const body = $input.first().json;

let messageText = '';
let chatId = null;
let userId = null;
let username = '';
let firstName = '';
let messageId = null;
let updateType = 'message';

if (body.message) {
  updateType = 'message';
  const msg = body.message;
  messageText = msg.text || msg.caption || '';
  chatId = msg.chat.id;
  userId = msg.from?.id;
  username = msg.from?.username || '';
  firstName = msg.from?.first_name || 'User';
  messageId = msg.message_id;
} else if (body.callback_query) {
  updateType = 'callback_query';
  const cb = body.callback_query;
  messageText = cb.data || '';
  chatId = cb.message?.chat?.id;
  userId = cb.from?.id;
  username = cb.from?.username || '';
  firstName = cb.from?.first_name || 'User';
  messageId = cb.message?.message_id;
} else if (body.edited_message) {
  updateType = 'edited_message';
  const emsg = body.edited_message;
  messageText = emsg.text || emsg.caption || '';
  chatId = emsg.chat.id;
  userId = emsg.from?.id;
  username = emsg.from?.username || '';
  firstName = emsg.from?.first_name || 'User';
  messageId = emsg.message_id;
}

// Guard: skip if message empty or bot message
if (!messageText.trim() || !chatId) {
  return [];
}

// Normalize text
messageText = messageText.trim();

return [{
  json: {
    messageText,
    chatId,
    userId,
    username,
    firstName,
    messageId,
    updateType,
    receivedAt: new Date().toISOString()
  }
}];

// ========================================
// BUILD AI REQUEST
// Combines: prompt + memory + user message
// Prepares payload for Groq LLM
// ========================================
const items = $input.all();

// Item 0: Normalized message (from before merge)
const msgData = (() => {
  for (const item of items) {
    if (item.json.messageText !== undefined) return item.json;
  }
  return {};
})();

// Item 1: Prompt response
const promptData = (() => {
  for (const item of items) {
    if (item.json.data && item.json.intent === 'list_prompts') return item.json.data;
    if (item.json.data && Array.isArray(item.json.data)) return item.json.data;
  }
  return [];
})();

// Item 2: Memory response
const memoryData = (() => {
  for (const item of items) {
    if (item.json.data && item.json.intent === 'list_ai_memories') return item.json.data;
    if (item.json.resource === 'ai_memory') return item.json.data || [];
  }
  return [];
})();

// Extract active system prompt
const prompts = Array.isArray(promptData) ? promptData : (promptData?.data || []);
const systemPromptObj = prompts.find(p => p.active && p.name === 'system') ||
                        prompts.find(p => p.active) ||
                        { prompt: '' };

const systemPrompt = systemPromptObj.prompt ||
  `Kamu adalah FinTrack AI, asisten keuangan pribadi berbasis Telegram.
Tugasmu adalah membantu pengguna mencatat, menganalisis, dan mengelola keuangan mereka.

Panggil user dengan nama mereka. Gunakan bahasa Indonesia yang ramah dan profesional.

Kamu WAJIB merespons HANYA dalam format JSON berikut:
{
  "intent": "<nama_intent>",
  "message": "<pesan_untuk_user>",
  "parameters": { <parameter_yang_diperlukan> }
}

Daftar intent yang tersedia:
- create_transaction: catat transaksi (wajib: type, amount, category, description, transaction_date)
- update_transaction: update transaksi (wajib: id; opsional: type, amount, category, description, transaction_date)
- delete_transaction: hapus transaksi (wajib: id)
- create_budget: buat budget (wajib: name, amount, period)
- update_budget: update budget (wajib: id)
- delete_budget: hapus budget (wajib: id)
- budget: lihat ringkasan budget
- balance: cek saldo
- create_reminder: buat pengingat (wajib: title, remind_at)
- list_reminders: lihat semua pengingat
- create_bill: catat tagihan rutin (wajib: name, amount, billing_date)
- list_bills: lihat tagihan
- create_saving_goal: buat target tabungan (wajib: name, target_amount)
- saving_progress: progres tabungan
- list_categories: lihat kategori
- create_category: buat kategori (wajib: name, type)
- statistics: lihat statistik keuangan
- daily_report: laporan harian (opsional: date)
- weekly_report: laporan mingguan (opsional: start_date, end_date)
- monthly_report: laporan bulanan (opsional: year, month)
- ai_insight: analisis keuangan AI
- ai_prediction: prediksi keuangan
- ai_recommendation: rekomendasi keuangan
- dashboard: ringkasan dashboard
- greeting: sapa pengguna
- help: tampilkan bantuan
- unknown: pesan tidak dikenal`;

// Build memory context string
const memories = Array.isArray(memoryData) ? memoryData : (memoryData?.data || []);
const activeMemories = memories.filter(m => m.active !== false);
const memoryContext = activeMemories.length > 0
  ? '\n\nKonteks Memory User:\n' + activeMemories.map(m => `- ${m.key}: ${m.value}`).join('\n')
  : '';

return [{
  json: {
    // Pass through message data
    ...msgData,
    // AI Request payload
    aiRequest: {
      model: 'llama-3.3-70b-versatile',
      messages: [
        {
          role: 'system',
          content: systemPrompt + memoryContext
        },
        {
          role: 'user',
          content: `User: ${msgData.firstName || 'User'}\nPesan: ${msgData.messageText}`
        }
      ],
      temperature: 0.1,
      max_tokens: 512,
      response_format: { type: 'json_object' }
    }
  }
}];

// ========================================
// PARSE GROQ RESPONSE
// Extract intent + parameters + message
// from Groq JSON response
// ========================================
const item = $input.first().json;
const prevItem = $('🛠️ Build AI Request').first().json;

let intent = 'unknown';
let message = '';
let parameters = {};
let aiRawContent = '';

try {
  aiRawContent = item.choices?.[0]?.message?.content || '{}';
  const parsed = JSON.parse(aiRawContent);
  intent = (parsed.intent || 'unknown').toLowerCase().trim();
  message = parsed.message || '';
  parameters = parsed.parameters || {};
} catch (e) {
  intent = 'unknown';
  message = 'Maaf, saya tidak dapat memahami permintaan Anda. Coba ulangi dengan kalimat yang lebih jelas.';
  parameters = {};
}

// Inject user context into parameters
parameters._user_id = prevItem.userId;
parameters._username = prevItem.username;
parameters._chat_id = prevItem.chatId;
parameters._first_name = prevItem.firstName;

// Classify intent into groups for routing
const AI_MODULE_INTENTS = ['ai_insight', 'ai_prediction', 'ai_recommendation'];
const REPORT_INTENTS = ['daily_report', 'weekly_report', 'monthly_report', 'statistics'];
const SYSTEM_INTENTS = ['greeting', 'help', 'unknown', 'telegram_status', 'dashboard', 'dashboard_summary'];

let intentGroup = 'crud';
if (AI_MODULE_INTENTS.includes(intent)) intentGroup = 'ai_module';
else if (REPORT_INTENTS.includes(intent)) intentGroup = 'report';
else if (SYSTEM_INTENTS.includes(intent)) intentGroup = 'system';

return [{
  json: {
    ...prevItem,
    intent,
    intentGroup,
    aiMessage: message,
    parameters,
    aiRawContent
  }
}];

