// ========================================
// FORMAT TELEGRAM RESPONSE
// Converts Laravel API response into
// user-friendly Telegram MarkdownV2 message
// ========================================
const allItems = $input.all();
const item = allItems[0]?.json || {};

// Get original parsed data from intent router step
const parsedCtx = $('🔍 Parse Groq Response').first().json;
const chatId = parsedCtx.chatId;
const intent = parsedCtx.intent;
const aiMessage = parsedCtx.aiMessage || '';
const firstName = parsedCtx.firstName || 'User';

// Determine source of this item
const isGroqAiResponse = item.choices !== undefined;
const isLaravelResponse = item.success !== undefined;

let replyText = '';

if (isGroqAiResponse) {
  // AI Module response (insight/prediction/recommendation)
  replyText = item.choices?.[0]?.message?.content || 'Maaf, tidak dapat menghasilkan analisis saat ini.';

} else if (isLaravelResponse) {
  const success = item.success;
  const data = item.data;
  const laravelMessage = item.message || '';
  const laravelIntent = item.intent || intent;

  if (!success) {
    replyText = `❌ *Gagal memproses permintaan*\n${laravelMessage || 'Terjadi kesalahan. Coba ulangi.'}`;
  } else {
    switch (laravelIntent) {
      case 'create_transaction':
        replyText = `✅ *Transaksi Dicatat*\n💰 ${data?.type === 'income' ? 'Pemasukan' : 'Pengeluaran'}: Rp ${Number(data?.amount || 0).toLocaleString('id-ID')}\n📁 Kategori: ${data?.category || '-'}\n📝 ${data?.description || '-'}\n📅 ${data?.transaction_date || '-'}`;
        break;
      case 'update_transaction':
        replyText = `✅ *Transaksi Diperbarui*\n💰 ${data?.type === 'income' ? 'Pemasukan' : 'Pengeluaran'}: Rp ${Number(data?.amount || 0).toLocaleString('id-ID')}\n📁 Kategori: ${data?.category || '-'}\n📝 ${data?.description || '-'}`;
        break;
      case 'delete_transaction':
        replyText = `🗑️ Transaksi berhasil dihapus.`;
        break;
      case 'create_budget':
        replyText = `✅ *Budget Dibuat*\n📋 ${data?.name || '-'}\n💵 Rp ${Number(data?.amount || 0).toLocaleString('id-ID')} / ${data?.period || '-'}`;
        break;
      case 'budget':
      case 'balance':
        if (Array.isArray(data)) {
          const lines = data.map(b => `📊 ${b.name}: Rp ${Number(b.amount || 0).toLocaleString('id-ID')}`).join('\n');
          replyText = `💼 *Ringkasan Budget Anda*\n${lines || 'Belum ada budget.'}`;
        } else {
          replyText = `💼 *Budget*\n${laravelMessage}`;
        }
        break;
      case 'create_reminder':
        replyText = `⏰ *Pengingat Dibuat*\n📌 ${data?.title || '-'}\n🕐 ${data?.remind_at || '-'}`;
        break;
      case 'list_reminders':
        if (Array.isArray(data) && data.length > 0) {
          const lines = data.map((r, i) => `${i+1}. ⏰ ${r.title} — ${r.remind_at}`).join('\n');
          replyText = `📋 *Pengingat Anda*\n${lines}`;
        } else {
          replyText = '📋 Tidak ada pengingat aktif.';
        }
        break;
      case 'create_bill':
        replyText = `✅ *Tagihan Dicatat*\n🏷️ ${data?.name || '-'}\n💵 Rp ${Number(data?.amount || 0).toLocaleString('id-ID')}\n📅 Tanggal tagih: ${data?.billing_date || '-'}`;
        break;
      case 'list_bills':
        if (Array.isArray(data) && data.length > 0) {
          const lines = data.map((b, i) => `${i+1}. 🏷️ ${b.name}: Rp ${Number(b.amount||0).toLocaleString('id-ID')} (tgl ${b.billing_date})`).join('\n');
          replyText = `🧾 *Tagihan Rutin*\n${lines}`;
        } else {
          replyText = '🧾 Tidak ada tagihan rutin.';
        }
        break;
      case 'create_saving_goal':
        replyText = `🎯 *Target Tabungan Dibuat*\n📌 ${data?.name || '-'}\n💰 Target: Rp ${Number(data?.target_amount || 0).toLocaleString('id-ID')}`;
        break;
      case 'saving_progress':
        if (Array.isArray(data)) {
          const lines = data.map(g => `🎯 ${g.name}\n   Terkumpul: Rp ${Number(g.current_amount||0).toLocaleString('id-ID')} / Rp ${Number(g.target_amount||0).toLocaleString('id-ID')}`).join('\n');
          replyText = `📈 *Progres Tabungan*\n${lines}`;
        } else {
          replyText = laravelMessage || 'Lihat progres tabungan Anda di dashboard.';
        }
        break;
      case 'statistics':
        replyText = `📊 *Statistik Keuangan*\n${aiMessage || laravelMessage || 'Data statistik berhasil diambil. Buka dashboard untuk melihat detail.'}`;
        break;
      case 'daily_report':
      case 'weekly_report':
      case 'monthly_report': {
        const report = data?.report || data || {};
        const period = laravelIntent === 'daily_report' ? 'Harian' : laravelIntent === 'weekly_report' ? 'Mingguan' : 'Bulanan';
        const income = report.total_income || report.income || 0;
        const expense = report.total_expense || report.expense || 0;
        const net = Number(income) - Number(expense);
        replyText = `📅 *Laporan ${period}*\n💚 Pemasukan: Rp ${Number(income).toLocaleString('id-ID')}\n🔴 Pengeluaran: Rp ${Number(expense).toLocaleString('id-ID')}\n📊 Selisih: Rp ${net.toLocaleString('id-ID')}`;
        break;
      }
      case 'list_categories':
        if (Array.isArray(data) && data.length > 0) {
          const incomes = data.filter(c => c.type === 'income').map(c => c.name).join(', ');
          const expenses = data.filter(c => c.type === 'expense').map(c => c.name).join(', ');
          replyText = `📂 *Kategori*\n💚 Pemasukan: ${incomes || '-'}\n🔴 Pengeluaran: ${expenses || '-'}`;
        } else {
          replyText = '📂 Belum ada kategori.';
        }
        break;
      case 'create_category':
        replyText = `✅ *Kategori Dibuat*\n📁 ${data?.name || '-'} (${data?.type || '-'})`;
        break;
      case 'greeting':
        replyText = `👋 Halo, *${firstName}*!\n\n${laravelMessage || 'Saya FinTrack AI, asisten keuangan pribadi Anda. Ada yang bisa saya bantu?'}\n\nKetik /help untuk melihat yang bisa saya lakukan.`;
        break;
      case 'help':
        replyText = `🤖 *FinTrack AI - Panduan Penggunaan*\n\n*Transaksi*\n• "catat pengeluaran makan 25rb"\n• "tambah pemasukan gaji 5jt"\n\n*Budget*\n• "buat budget makan 1jt/bulan"\n• "cek budget saya"\n\n*Laporan*\n• "laporan hari ini"\n• "laporan minggu ini"\n• "laporan bulan ini"\n\n*Tabungan*\n• "buat target tabungan liburan 5jt"\n• "progres tabungan saya"\n\n*Pengingat*\n• "ingatkan saya bayar listrik tiap tgl 5"\n\n*AI Analysis*\n• "analisis keuangan saya"\n• "prediksi pengeluaran bulan depan"\n• "rekomendasi hemat"`;
        break;
      case 'dashboard':
      case 'dashboard_summary':
        replyText = `📊 *Dashboard FinTrack AI*\n\n${laravelMessage || 'Buka dashboard untuk melihat ringkasan keuangan lengkap Anda.'}\n\n${aiMessage || ''}`;
        break;
      case 'unknown':
      default:
        replyText = `🤔 ${aiMessage || 'Maaf, saya tidak mengerti permintaan Anda. Ketik /help untuk melihat panduan penggunaan.'}`;
        break;
    }
  }

} else {
  // Fallback
  replyText = `🤔 ${aiMessage || 'Maaf, terjadi kesalahan. Coba ulangi permintaan Anda.'}`;
}

// Safety: sanitize special Markdown chars if needed
// (Using Markdown mode 'Markdown' not MarkdownV2 for simpler escaping)
return [{
  json: {
    chatId,
    replyText,
    intent,
    parseMode: 'Markdown'
  }
}];

// ========================================
// ERROR HANDLER
// Send error notification to Telegram
// ========================================
const error = $input.first().json;
const executionId = $execution?.id || 'unknown';
const workflowName = $workflow?.name || 'FinTrack AI Bot';

const errorMessage = error.error?.message || error.message || JSON.stringify(error);
const nodeName = error.execution?.lastNodeExecuted || 'unknown node';

// Try to get chatId from the failed execution context
const chatId = $env.TELEGRAM_ADMIN_CHAT_ID || error.execution?.data?.resultData?.runData?.['🔧 Normalize Message']?.[0]?.data?.main?.[0]?.[0]?.json?.chatId;

return [{
  json: {
    chatId: chatId || $env.TELEGRAM_ADMIN_CHAT_ID,
    errorMessage,
    nodeName,
    executionId,
    workflowName
  }
}];

